const webhook = $('GitHub Webhook').first().json.body;
const runs = $input.first().json.workflow_runs || [];
let failedRun = runs.find(r => r.conclusion === 'failure');
if (!failedRun) failedRun = runs.find(r => r.status === 'completed');
if (!failedRun) failedRun = runs[0];
if (!failedRun) throw new Error('No workflow run found for SHA ' + webhook.check_suite.head_sha);
const repo = webhook.repository.full_name;
const branch = webhook.check_suite.head_branch || failedRun.head_branch;
let prNumber = null;
const prs = webhook.check_suite.pull_requests || [];
if (prs.length > 0) prNumber = prs[0].number;
let issueNumber = null;
const branchMatch = branch.match(/^[bfrodec]\/#(\d+)/) || branch.match(/issue-(\d+)/);
if (branchMatch) issueNumber = parseInt(branchMatch[1]);
const commentTarget = prNumber || issueNumber;
const headCommitMsg = (failedRun.head_commit && failedRun.head_commit.message) || '';
const skip_autofix = headCommitMsg.startsWith('[auto-fix]');
return [{ json: { run_id: failedRun.id, run_name: failedRun.name, run_url: failedRun.html_url, repo, branch, comment_target: commentTarget, skip_autofix } }];

const jobs = $input.first().json.jobs || [];
const failedJob = jobs.find(j => j.conclusion === 'failure');
if (!failedJob) throw new Error('No failed job found in run ' + $('Extract Run Info').first().json.run_id);
const ctx = $('Extract Run Info').first().json;
// Build step summary for Claude
const stepSummary = failedJob.steps.map(s => `  ${s.conclusion === 'failure' ? '❌' : '✅'} ${s.name}: ${s.conclusion}`).join('\n');
return [{ json: { job_id: failedJob.id, job_name: failedJob.name, step_summary: stepSummary, ...ctx } }];

const response = $input.first().json;
const headers = response.headers || {};
const location = headers.location || headers.Location || '';
const ctx = $('Extract Failed Job').first().json;
if (!location) {
  // Fallback: provide step summary only
  return [{ json: { logs: 'Raw logs unavailable. Step summary:\n' + ctx.step_summary, has_logs: false, ...ctx } }];
}
return [{ json: { log_url: location, has_logs: true, ...ctx } }];

const ctx = $('Extract Log URL').first().json;
let logs;
if (ctx.has_logs) {
  const rawLogs = $input.first().json.data || $input.first().json || '';
  logs = typeof rawLogs === 'string' ? rawLogs.substring(0, 30000) : JSON.stringify(rawLogs).substring(0, 30000);
} else {
  logs = ctx.logs;
}
const requestBody = {
  model: 'claude-sonnet-4-6',
  max_tokens: 4096,
  messages: [{
    role: 'user',
    content: 'You are a CI/CD debugging expert. A GitHub Actions job failed.

'      + 'Provide your response in EXACTLY this format:
'      + 'SUMMARY: [one sentence describing the root cause and fix]
'      + '---
'      + '[full detailed analysis including:
'      + '1. Root cause of the failure
'      + '2. The specific file(s) and line(s) to fix
'      + '3. The exact code change needed (as a diff)
'      + '4. Any additional context]

'      + 'If the fix is a single-file text replacement, also append EXACTLY this block after your analysis:
'      + 'AUTO_FIX_FILE: path/to/file
'      + 'AUTO_FIX_OLD:
'      + '<exact lines to replace, copied verbatim from the file>
'      + 'AUTO_FIX_END
'      + 'AUTO_FIX_NEW:
'      + '<exact replacement lines>
'      + 'AUTO_FIX_END

'      + 'Rules for the AUTO_FIX block:
'      + '- Only include it if you are confident in a single-file fix
'      + '- AUTO_FIX_FILE must be a repo-relative path (e.g. app/src/main.py)
'      + '- AUTO_FIX_OLD must match the file content exactly (whitespace matters)
'      + '- If the fix spans multiple files or you are unsure, omit the AUTO_FIX block entirely

'      + 'Failed job: ' + ctx.job_name + '
'      + 'Branch: ' + ctx.branch + '
'      + 'Step summary:
' + ctx.step_summary + '

'      + 'Logs (truncated to 30K chars):
' + logs
  }]
};
return [{ json: requestBody }];

const claudeText = $input.first().json.content[0].text;
const ctx = $('Extract Log URL').first().json;
const runInfo = $('Extract Run Info').first().json;
let summary = 'CI failure diagnosed on `' + ctx.job_name + '`.';
let details = claudeText;
const parts = claudeText.split(/^---$/m);
if (parts.length >= 2) {
  const match = parts[0].trim().match(/^SUMMARY:\s*(.+)/i);
  if (match) summary = match[1].trim();
  details = parts.slice(1).join('---').trim();
}
const body = '> \uD83E\uDD16 **This is an automated message from the DevLLMOps AI Agent**\n\n'
  + '**' + summary + '**\n\n'
  + '<details>\n<summary>View full CI failure analysis</summary>\n\n'
  + details + '\n\n'
  + '---\n'
  + '*Failed job: `' + ctx.job_name + '` | Branch: `' + ctx.branch + '` | [View run](' + ctx.run_url + ')*\n\n'
  + '</details>';
return [{ json: { body, claude_text: claudeText, summary, repo: ctx.repo, branch: ctx.branch, comment_target: ctx.comment_target, skip_autofix: runInfo.skip_autofix } }];

const prev = $('Build Analysis Comment').first().json;
const text = prev.claude_text || '';
let has_fix = false;
let fix_file = '';
let fix_old = '';
let fix_new = '';
const fileMatch = text.match(/AUTO_FIX_FILE:\s*(.+)/);
const oldMatch = text.match(/AUTO_FIX_OLD:\n([\s\S]*?)\nAUTO_FIX_END/);
const newMatch = text.match(/AUTO_FIX_NEW:\n([\s\S]*?)\nAUTO_FIX_END/);
if (fileMatch && oldMatch && newMatch) {
  fix_file = fileMatch[1].trim();
  fix_old = oldMatch[1];
  fix_new = newMatch[1];
  has_fix = true;
}
return [{ json: { has_fix, fix_file, fix_old, fix_new, summary: prev.summary, repo: prev.repo, branch: prev.branch, comment_target: prev.comment_target, skip_autofix: prev.skip_autofix } }];

const prev = $('Parse Auto-Fix').first().json;
const fileData = $input.first().json;
const content = Buffer.from(fileData.content.replace(/\n/g, ''), 'base64').toString('utf8');
const fixed = content.replace(prev.fix_old, prev.fix_new);
if (fixed === content) throw new Error('AUTO_FIX_OLD not found in file ' + prev.fix_file + '. The exact string match failed.');
const encodedContent = Buffer.from(fixed).toString('base64');
const commitMsg = '[auto-fix] ' + prev.summary;
return [{ json: { message: commitMsg, content: encodedContent, sha: fileData.sha, branch: prev.branch, path: prev.fix_file, repo: prev.repo, comment_target: prev.comment_target, summary: prev.summary } }];

const webhook = $('GitHub Webhook').first().json.body;
const conclusion = webhook.check_suite.conclusion;
const branch = webhook.check_suite.head_branch || '';
const repo = webhook.repository.full_name;
const owner = webhook.repository.owner.login;
const protectedBranches = ['main', 'master', 'release', 'develop'];
const should_create_pr = conclusion === 'success' && !protectedBranches.includes(branch);
let issueNumber = null;
const branchMatch = branch.match(/^[bfrodec]\/#(\d+)/) || branch.match(/issue-(\d+)/);
if (branchMatch) issueNumber = parseInt(branchMatch[1]);
return [{ json: { repo, owner, branch, issue_number: issueNumber, should_create_pr } }];

const prev = $('Extract Branch Info').first().json;
const items = $input.all();
const has_existing_pr = items.some(item => item.json && item.json.number !== undefined);
const prefixMap = { b: 'Bug Fix', f: 'Feature', r: 'Refactor', o: 'Ops', d: 'Docs', e: 'Enhancement' };
const branch = prev.branch;
const branchMatch = branch.match(/^([bfrodec])\/#(\d+)-(.+)/);
let title, body;
if (branchMatch) {
  const prefix = prefixMap[branchMatch[1]] || 'Update';
  const num = branchMatch[2];
  const slug = branchMatch[3].replace(/-/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  title = prefix + ': ' + slug + ' (#' + num + ')';
  body = '> \uD83E\uDD16 **This is an automated PR created by the DevLLMOps AI Agent**\n\n'
    + 'CI passed on branch `' + branch + '`. This PR was auto-created for review.\n\n'
    + 'Closes #' + num;
} else {
  const slug = branch.replace(/[-_\/]/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
  title = slug;
  body = '> \uD83E\uDD16 **This is an automated PR created by the DevLLMOps AI Agent**\n\n'
    + 'CI passed on branch `' + branch + '`. This PR was auto-created for review.';
}
return [{ json: { has_existing_pr, title, body, ...prev } }];
